const item = $input.first();
const body = item.json.body || item.json;
const base64 = body.imageBase64;
const mimeType = body.mimeType || 'image/png';

if (!base64) throw new Error('imageBase64 manquant');

return [{
  json: {
    model: 'nvidia/nemotron-nano-12b-v2-vl:free',
    messages: [{
      role: 'user',
      content: [
        { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64}` } },
        { type: 'text', text: 'You are an expert frontend developer. Analyze this UI wireframe or mockup image and generate clean HTML and CSS code that recreates it faithfully. Return ONLY a raw JSON object with exactly two keys: "html" (body content only, no html/head/body tags) and "css" (all styles as a plain string). No explanation, no markdown, no code fences. Raw JSON only.' }
      ]
    }],
    max_tokens: 3000
  }
}];

const ELEMENT_TEMPLATES = {
  button: '<button style="padding:10px 24px;border:2px solid #333;background:#f5f5f5;border-radius:4px;font-size:14px;cursor:pointer">{label}</button>',
  input: '<input type="text" placeholder="{label}" style="padding:10px;border:2px solid #333;border-radius:4px;width:100%;max-width:300px;font-size:14px" />',
  textarea: '<textarea placeholder="{label}" style="padding:10px;border:2px solid #333;border-radius:4px;width:100%;max-width:400px;height:100px;font-size:14px"></textarea>',
  heading: '<h2 style="font-family:sans-serif;color:#333;border-bottom:2px solid #eee;padding-bottom:8px">{label}</h2>',
  navbar: '<nav style="display:flex;justify-content:space-between;align-items:center;padding:12px 24px;border-bottom:2px solid #333;background:#f9f9f9"><div style="font-size:18px;font-weight:bold;color:#333">Logo</div><div style="display:flex;gap:16px"><a href="#" style="text-decoration:none;color:#333">Home</a><a href="#" style="text-decoration:none;color:#333">About</a><a href="#" style="text-decoration:none;color:#333">Contact</a></div></nav>',
  card: '<div style="border:2px solid #333;border-radius:8px;padding:16px;max-width:300px;background:#fafafa"><div style="width:100%;height:120px;background:#e0e0e0;border-radius:4px;margin-bottom:12px"></div><h3 style="margin:0 0 8px 0;font-family:sans-serif;color:#333">{label}</h3><p style="margin:0;color:#666;font-size:14px">Description placeholder text goes here.</p></div>',
  form: '<form style="display:flex;flex-direction:column;gap:12px;max-width:400px;padding:24px;border:2px solid #333;border-radius:8px"><h3 style="margin:0;font-family:sans-serif;color:#333">{label}</h3><input type="text" placeholder="Name" style="padding:10px;border:2px solid #ccc;border-radius:4px" /><input type="email" placeholder="Email" style="padding:10px;border:2px solid #ccc;border-radius:4px" /><button style="padding:10px;background:#333;color:white;border:none;border-radius:4px;cursor:pointer">Submit</button></form>',
  image: '<div style="width:100%;max-width:400px;height:200px;background:#e0e0e0;border:2px dashed #999;border-radius:4px;display:flex;align-items:center;justify-content:center;color:#999;font-size:14px">[Image: {label}]</div>',
  menu: '<ul style="list-style:none;padding:0;border:2px solid #333;border-radius:4px;max-width:200px"><li style="padding:10px 16px;border-bottom:1px solid #eee;cursor:pointer">Menu Item 1</li><li style="padding:10px 16px;border-bottom:1px solid #eee;cursor:pointer">Menu Item 2</li><li style="padding:10px 16px;cursor:pointer">Menu Item 3</li></ul>'
};

const ELEMENT_KEYWORDS = {
  button: ['button','btn','bouton','submit','click'],
  input: ['input','field','champ','text field','search bar'],
  textarea: ['textarea','text area','message','description field'],
  heading: ['title','heading','titre','header text'],
  navbar: ['navbar','navigation','nav bar','menu bar','top bar'],
  card: ['card','carte','panel','box'],
  form: ['form','formulaire','login','register','signup','sign up','connexion'],
  image: ['image','photo','picture','illustration','logo'],
  menu: ['menu','sidebar','side bar','dropdown']
};

function detectElements(text) {
  const lower = text.toLowerCase();
  const detected = [];
  for (const [type, keywords] of Object.entries(ELEMENT_KEYWORDS)) {
    if (keywords.some(k => lower.includes(k)) && !detected.includes(type)) detected.push(type);
  }
  return detected;
}

function buildFallbackHtml(rawText) {
  const elements = detectElements(rawText);
  if (elements.length === 0) {
    elements.push('navbar','heading','card');
  }
  const sections = elements.map(el => {
    const label = el.charAt(0).toUpperCase() + el.slice(1);
    return (ELEMENT_TEMPLATES[el] || '').replace(/\{label\}/g, label);
  });
  return sections.join('\n');
}

const BASE_CSS = '* { margin:0; padding:0; box-sizing:border-box; } body { font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',sans-serif; background:#fff; color:#333; padding:24px; display:flex; flex-direction:column; gap:20px; align-items:flex-start; }';

const data = $input.first().json;

if (data.error) {
  const msg = typeof data.error === 'string' ? data.error : (data.error.message || JSON.stringify(data.error));
  return [{ json: { success: false, html: '', css: '', error: msg } }];
}

const rawText = data?.choices?.[0]?.message?.content || '';

if (!rawText) {
  return [{ json: { success: false, html: '', css: '', error: 'Aucune réponse', raw: JSON.stringify(data) } }];
}

let html = '';
let css = '';

try {
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    html = parsed.html || '';
    css = parsed.css || '';
  }
} catch(e) {}

if (!html) {
  const htmlMatch = rawText.match(/```html\s*([\s\S]*?)```/i) || rawText.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  if (htmlMatch) html = htmlMatch[1].trim();
}
if (!css) {
  const cssMatch = rawText.match(/```css\s*([\s\S]*?)```/i) || rawText.match(/<style[^>]*>([\s\S]*?)<\/style>/i);
  if (cssMatch) css = cssMatch[1].trim();
}

// Fallback : templates si aucun HTML exploitable
if (!html || html.length < 30) {
  html = buildFallbackHtml(rawText);
  css = BASE_CSS;
}

return [{ json: { success: true, html, css } }];
